import React, { ForwardedRef, forwardRef } from 'react';

import clsx from 'clsx';

import { logError } from '../../utils/helpers';
import { Icon } from '../Icon/Icon';
import { LoadingSpinner } from '../LoadingSpinner';
import { getStyles } from './IconButton.css';
import { IconButtonProps } from './IconButton.types';

export const IconButton = forwardRef(
  (
    {
      icon,
      variant = 'primary',
      size = 'medium',
      float = false,
      loading = false,
      disabled = false,
      className,
      ...rest
    }: IconButtonProps,
    ref: ForwardedRef<HTMLButtonElement>,
  ) => {
    const styles = getStyles({ variant, size, float, disabled, loading });
    const iconSize = size === 'large' ? 'medium' : size;
    const loadingSize = size === 'tiny' ? 'small' : size;
    const loadingColor = variant === 'primary' ? 'inverted' : 'default';

    logError(
      (variant === 'primary' || variant === 'secondary') && size === 'tiny',
      `Invalid combination: variant can't be ${variant} when size is 'tiny'`,
    );
    logError(
      variant === 'inherit' && loading === true,
      `Invalid combination: loading can't be true when variant is 'inherit'`,
    );
    logError(
      (variant === 'tertiary' || variant === 'inherit') && float === true,
      `Invalid combination: float can't be true when variant is ${variant}`,
    );

    return (
      <button
        disabled={disabled}
        className={clsx(styles, className)}
        type="button"
        {...rest}
        ref={ref}
      >
        {loading ? (
          <LoadingSpinner size={loadingSize} color={loadingColor} />
        ) : (
          <Icon size={iconSize} icon={icon} />
        )}
      </button>
    );
  },
);

IconButton.displayName = 'IconButton';
