import React from 'react';

import { User } from '@hexa-ui/icons';
import * as RadixAvatar from '@radix-ui/react-avatar';
import clsx from 'clsx';

import { Icon } from '../Icon';
import { Header, HeaderProps } from '../Typography/Header';
import { getStyles, imageStyles } from './Avatar.css';
import { AvatarProps } from './Avatar.types';

const INITIALS_SIZE = {
  tiny: 'h6',
  small: 'h6',
  medium: 'h5',
  large: 'h4',
};

export const Avatar = ({
  className,
  imageSrc,
  alt,
  variant = 'icon',
  size = 'medium',
  initialsLetters,
  disabled = false,
  ...rest
}: AvatarProps) => {
  const { Root, Image } = RadixAvatar;
  const rootStyles = getStyles({ size, variant, disabled });
  const sizeVariant = INITIALS_SIZE[size] as HeaderProps['variant'];

  const variantRenderers = {
    initials: () => <Header variant={sizeVariant}>{initialsLetters}</Header>,
    icon: () => <Icon size={size} icon={User} />,
    image: () => <Image className={imageStyles} src={imageSrc} alt={alt} />,
  };

  return (
    <Root className={clsx(rootStyles, className)} {...rest}>
      {variantRenderers[variant]()}
    </Root>
  );
};
