import React, { ComponentProps } from 'react';

export const loadingSpinnerSizeOptions = [
  'small',
  'medium',
  'large',
  'xlarge',
] as const;

export const loadingSpinnerColorOptions = ['default', 'inverted'] as const;

type DivElementProps = ComponentProps<'div'>;

export type LoadingSpinnerProps = React.PropsWithoutRef<DivElementProps> & {
  size?: (typeof loadingSpinnerSizeOptions)[number];
  color?: (typeof loadingSpinnerColorOptions)[number];
};
