import React, { ComponentProps } from 'react';

import {
  AccordionMultipleProps,
  AccordionContentProps as AccordionPrimitiveContentProps,
  AccordionItemProps as AccordionPrimitiveItemProps,
  AccordionSingleProps,
} from '@radix-ui/react-accordion';

export const accordionSizeOptions = ['small', 'large'] as const;

export type AccordionSize = (typeof accordionSizeOptions)[number];

type FilteredAccordionSingleProps = Omit<
  AccordionSingleProps,
  'disabled' | 'orientation' | 'dir'
>;
type FilteredAccordionMultipleProps = Omit<
  AccordionMultipleProps,
  'disabled' | 'orientation' | 'dir'
>;

export type AccordionRootProps = (
  | FilteredAccordionSingleProps
  | FilteredAccordionMultipleProps
) & {
  children: React.ReactNode;
  size?: AccordionSize;
};

type AccordionPrimitiveItemWithoutDisabled = Pick<
  AccordionPrimitiveItemProps,
  'value'
>;

export type AccordionItemProps = AccordionPrimitiveItemWithoutDisabled & {
  /** Pass `Accordion.Header` component */
  header?: React.ReactElement;
  /** If `true`, adds a divider between the header and content */
  divider?: boolean;
  children: React.ReactNode;
  className?: string;
};

export type AccordionTitleProps = ComponentProps<'div'> & {
  /** Header text */
  children: React.ReactNode;
  /** Icon imported from `@hexa-ui/icons` */
  icon?: React.FunctionComponent;
};

export type AccordionContentProps = AccordionPrimitiveContentProps;
