import { ComponentProps, FunctionComponent } from 'react';

export type Action = {
  label: string;
  onClick(): void;
};

export const alertVariants = ['info', 'success', 'warning', 'error'] as const;

type AlertElementProps = ComponentProps<'div'>;

export type AlertProps = React.PropsWithoutRef<AlertElementProps> & {
  variant?: (typeof alertVariants)[number];
  customIcon?: FunctionComponent;
  actions?: [firstAction: Action, secondAction?: Action];
  onClose?(): void;
};
