import React from 'react';

import clsx from 'clsx';

import {
  containerStyles,
  dotsStyles,
  firstDotStyles,
  secondDotStyles,
} from './LoadingSpinner.css';
import { LoadingSpinnerProps } from './LoadingSpinner.types';

export const LoadingSpinner = ({
  className,
  size = 'medium',
  color = 'default',
  ...rest
}: LoadingSpinnerProps) => {
  const componentsStyles = containerStyles({ size });
  const dotStyles = dotsStyles({ size, color });

  return (
    <div
      data-testid="loadingSpinner"
      className={clsx(componentsStyles, className)}
      {...rest}
    >
      <div
        data-testid="loadingDots"
        className={clsx(dotStyles, firstDotStyles())}
      />
      <div className={clsx(dotStyles, secondDotStyles())} />
      <div className={clsx(dotStyles)} />
    </div>
  );
};
