import React from 'react';

import { ChevronDown } from '@hexa-ui/icons';
import clsx from 'clsx';

import { Icon } from '../Icon';
import {
  chevronIconStyle,
  getIconStyle,
  getStyles,
} from './DropdownButton.css';
import { DropdownButtonProps } from './DropdownButton.types';

export const DropdownButton = React.forwardRef<
  HTMLButtonElement,
  DropdownButtonProps
>(
  (
    {
      className,
      children,
      icon: IconSvg,
      size = 'medium',
      open = false,
      disabled,
      ...rest
    }: DropdownButtonProps,
    ref,
  ) => {
    const styles = getStyles({ size, open });

    return (
      <button
        className={clsx(styles, className)}
        ref={ref}
        type="button"
        disabled={disabled}
        {...rest}
      >
        {IconSvg && <IconSvg className={getIconStyle({ size })} />}
        {children}
        <Icon
          icon={ChevronDown}
          size="small"
          className={chevronIconStyle({ open, disabled })}
        />
      </button>
    );
  },
);

DropdownButton.displayName = 'DropdownButton';
