import React from 'react';

import clsx from 'clsx';

import { getStyles } from './Card.css';
import { CardProps } from './Card.types';

export const Card = ({
  className,
  children,
  color = 'neutral',
  elevation = false,
  intensity = 'weak',
  ...rest
}: CardProps) => {
  const styles = getStyles({ colorVariant: color, elevation, intensity });

  return (
    <div className={clsx(styles, className)} {...rest}>
      {children}
    </div>
  );
};
