import { ComponentProps } from 'react';

export const sizeOptions = ['tiny', 'small', 'medium', 'large'] as const;
export const variantOptions = [
  'primary',
  'secondary',
  'tertiary',
  'inherit',
] as const;
type Variant = (typeof variantOptions)[number];
type Size = (typeof sizeOptions)[number];

type ConditionalProps =
  | {
      variant?: Exclude<Variant, 'tertiary' | 'inherit'>;
      size?: Exclude<Size, 'tiny'>;
      float?: boolean;
      loading?: boolean;
    }
  | {
      variant: 'tertiary';
      size?: Size;
      float?: never;
      loading?: boolean;
    }
  | {
      variant: 'inherit';
      size?: Size;
      float?: never;
      loading?: never;
    };

type ButtonElementProps = ComponentProps<'button'>;

export type IconButtonProps = ButtonElementProps &
  ConditionalProps & {
    icon: React.FunctionComponent;
    disabled?: boolean;
  };
